ea><div class="flex flex-wrap gap-3"><select name="citation_style" class="rounded-xl border-slate-300"><?php $__currentLoopData = ['apa','mla','chicago','harvard','ieee','vancouver']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $style): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option><?php echo e($style); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><label class="p-2"><input type="checkbox" name="is_active" value="1" checked> Activate for future projects</label><button class="rounded-xl bg-indigo-600 px-4 py-2 text-white">Create immutable version</button></div></form></section><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><?php echo e($types->links()); ?><?php $__env->stopSection(); ?>

